validator:
function validate(input) {
  const [{ Products = [], Discounts = [] }] = input;
  const ids = new Set(), categories = new Set();
  for (const [id, category, price] of Products) {
    if (id === null || category === null || price === null) return 'Products rows may not contain null.';
    if (ids.has(id)) return `product_id ${id} appears twice.`;
    ids.add(id);
    if (price < 0) return `Product ${id} has a negative price.`;
  }
  for (const [category, discount] of Discounts) {
    if (category === null || discount === null) return 'Discounts rows may not contain null.';
    const key = category.toLowerCase();
    if (categories.has(key)) return `Category ${category} has two discounts.`;
    categories.add(key);
    if (discount < 0 || discount > 100) return `The discount for ${category} must be from 0 to 100.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const small = size === 'small';
  const categories = small ? ['Electronics', 'Clothing', 'Home', 'Toys', 'Books'] : Array.from({ length: 25 }, (_, i) => `Category ${i + 1}`);
  const rates = [0, 5, 10, 15, 20, 25, 33, 50, 75, 100];
  const Products = [], Discounts = [];
  const count = small ? pick(9) : 2000;
  for (let i = 0; i < count; i++) {
    const id = small ? 1 + 2 * i + pick(2) : i + 1;
    // Small cases mix round prices with odd ones so some final prices have decimals.
    const price = small ? (pick(2) ? 50 * (1 + pick(30)) : 1 + pick(999)) : pick(10000);
    Products.push([id, categories[pick(categories.length)], price]);
  }
  for (const category of categories) if (rand() < (small ? 0.5 : 0.7)) Discounts.push([category, small ? rates[pick(rates.length)] : pick(101)]);
  for (const rows of [Products, Discounts]) for (let i = rows.length - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ Products, Discounts }];
}
